/* ── Inscript Keyboard Mapping ── */
const INS = {
  "1":"१","2":"२","3":"३","4":"४","5":"५","6":"६","7":"७","8":"८","9":"९","0":"०","=":"ृ",
  "q":"ौ","w":"ै","e":"ा","r":"ी","t":"ू","y":"ब","u":"ह","i":"ग","o":"द","p":"ज","[":"ड","]":"़","\\":"ॉ",
  "a":"ो","s":"े","d":"्","f":"ि","g":"ु","h":"प","j":"र","k":"क","l":"त",";":"च","'":"ट",
  "x":"ं","c":"म","v":"न","b":"व","n":"ल","m":"स","/":"य",
  "@":"ॅ","#":"्र","$":"र्","%":"ज्ञ","^":"त्र","&":"क्ष","*":"श्र","_":"ः","+":"ऋ",
  "Q":"औ","W":"ऐ","E":"आ","R":"ई","T":"ऊ","Y":"भ","U":"ङ","I":"घ","O":"ध","P":"झ","{":"ढ","}":"ञ","|":"ऑ",
  "A":"ओ","S":"ए","D":"अ","F":"इ","G":"उ","H":"फ","K":"ख","L":"थ",":":"छ","\"":"ठ",
  "X":"ँ","C":"ण","N":"ळ","M":"श","<":"ष",">":"।"
};
const SHIFT_KEYS = "@#$%^&*_+QWERTYUIOP{}|ASDFGHKL:\"XCNM<>";

function keyLabel(k) {
  const shifted = SHIFT_KEYS.includes(k);
  const disp = /[a-z]/.test(k) ? k.toUpperCase() : k;
  return shifted ? "⇧" + disp : disp;
}
const REV = {};
for (const [k, v] of Object.entries(INS)) { if (!(v in REV)) REV[v] = keyLabel(k); }
REV[","] = ","; REV["."] = "."; REV[" "] = "Space";

const SPECIAL3 = ["ज्ञ","त्र","क्ष","श्र"];

function keysForWord(word) {
  const cp = Array.from(word);
  const out = [];
  let i = 0;
  while (i < cp.length) {
    const three = cp.slice(i, i + 3).join("");
    if (SPECIAL3.includes(three)) { out.push({u: three, k: REV[three]}); i += 3; continue; }
    const two = cp.slice(i, i + 2).join("");
    if (two === "्र") { out.push({u: "्र", k: REV["्र"]}); i += 2; continue; }
    if (two === "र्" && cp[i + 2]) { out.push({u: "र्", k: REV["र्"]}); i += 2; continue; }
    out.push({u: cp[i], k: REV[cp[i]] || "?"});
    i++;
  }
  return out;
}

/* ── Web Audio Synthesizer for Keystrokes ── */
let audioCtx = null;
let soundEnabled = (localStorage.getItem("tg-sound") === "on"); // Default is false/off

function initAudioContext() {
  try {
    if (!audioCtx) {
      const AudioCtxClass = window.AudioContext || window.webkitAudioContext;
      if (AudioCtxClass) audioCtx = new AudioCtxClass();
    }
    if (audioCtx && audioCtx.state === "suspended") {
      audioCtx.resume().catch(() => {});
    }
  } catch (e) {}
}

// Ensure audio context resumes on any user interaction when sound is on
window.addEventListener("click", () => {
  if (soundEnabled) initAudioContext();
}, { passive: true });
window.addEventListener("keydown", () => {
  if (soundEnabled) initAudioContext();
}, { passive: true });

function setSoundEnabled(enabled, persist = true) {
  soundEnabled = !!enabled;
  if (persist) {
    localStorage.setItem("tg-sound", soundEnabled ? "on" : "off");
  }
  if (soundEnabled) {
    initAudioContext();
    // Play preview sound when user explicitly enables it
    if (persist) {
      setTimeout(() => playKeySound("key"), 30);
    }
  }

  // Sync Setup Seg Buttons
  document.querySelectorAll("#soundSeg button").forEach(b => {
    b.classList.toggle("active", (b.dataset.sound === "on") === soundEnabled);
  });

  // Sync Practice Seg Buttons
  document.querySelectorAll("#pracSoundSeg button").forEach(b => {
    b.classList.toggle("active", (b.dataset.sound === "on") === soundEnabled);
  });

  // Sync Exam Pill Audio Button
  const muteIcon = document.getElementById("audioIconMute");
  const onIcon = document.getElementById("audioIconOn");
  const audioBtn = document.getElementById("audioToggleBtn");
  if (muteIcon) muteIcon.style.display = soundEnabled ? "none" : "";
  if (onIcon) onIcon.style.display = soundEnabled ? "" : "none";
  if (audioBtn) {
    audioBtn.classList.toggle("active", soundEnabled);
    audioBtn.title = soundEnabled ? "Typing Sound: ON (Click to Mute)" : "Typing Sound: OFF (Click to Unmute)";
  }

  // Sync Practice Topbar Button
  const pracAudioBtn = document.getElementById("pracAudioToggleBtn");
  if (pracAudioBtn) {
    const pracMute = pracAudioBtn.querySelector(".sound-icon-mute");
    const pracOn = pracAudioBtn.querySelector(".sound-icon-on");
    if (pracMute) pracMute.style.display = soundEnabled ? "none" : "";
    if (pracOn) pracOn.style.display = soundEnabled ? "" : "none";
    pracAudioBtn.classList.toggle("active", soundEnabled);
    pracAudioBtn.title = soundEnabled ? "Typing Sound: ON (Click to Turn Off)" : "Typing Sound: OFF (Click to Turn On)";
  }
}
window.setSoundEnabled = setSoundEnabled;

function playKeySound(type = "key") {
  if (!soundEnabled) return;
  try {
    initAudioContext();
    if (!audioCtx) return;

    const now = audioCtx.currentTime;
    const pitchMod = 0.93 + Math.random() * 0.14;

    if (type === "space") {
      // Spacebar: Rich deep mechanical clack + bottom-out thump
      const dur = 0.055;
      const bufSize = Math.floor(audioCtx.sampleRate * dur);
      const buffer = audioCtx.createBuffer(1, bufSize, audioCtx.sampleRate);
      const data = buffer.getChannelData(0);
      for (let i = 0; i < bufSize; i++) {
        data[i] = (Math.random() * 2 - 1) * Math.exp(-i / (bufSize * 0.25));
      }
      const noise = audioCtx.createBufferSource();
      noise.buffer = buffer;

      const bandpass = audioCtx.createBiquadFilter();
      bandpass.type = "bandpass";
      bandpass.frequency.setValueAtTime(1100 * pitchMod, now);
      bandpass.Q.setValueAtTime(1.8, now);

      const nGain = audioCtx.createGain();
      nGain.gain.setValueAtTime(0.45, now);
      nGain.gain.exponentialRampToValueAtTime(0.001, now + dur);

      noise.connect(bandpass);
      bandpass.connect(nGain);
      nGain.connect(audioCtx.destination);
      noise.start(now);

      // Low body tone (thump)
      const osc = audioCtx.createOscillator();
      const oGain = audioCtx.createGain();
      osc.type = "triangle";
      osc.frequency.setValueAtTime(210 * pitchMod, now);
      osc.frequency.exponentialRampToValueAtTime(55, now + 0.065);

      oGain.gain.setValueAtTime(0.55, now);
      oGain.gain.exponentialRampToValueAtTime(0.001, now + 0.065);

      osc.connect(oGain);
      oGain.connect(audioCtx.destination);
      osc.start(now);
      osc.stop(now + 0.07);

    } else if (type === "backspace") {
      // Backspace: Crisp dual-snap mechanical return
      const dur = 0.04;
      const bufSize = Math.floor(audioCtx.sampleRate * dur);
      const buffer = audioCtx.createBuffer(1, bufSize, audioCtx.sampleRate);
      const data = buffer.getChannelData(0);
      for (let i = 0; i < bufSize; i++) {
        data[i] = (Math.random() * 2 - 1) * Math.exp(-i / (bufSize * 0.2));
      }
      const noise = audioCtx.createBufferSource();
      noise.buffer = buffer;

      const filter = audioCtx.createBiquadFilter();
      filter.type = "highpass";
      filter.frequency.setValueAtTime(2200 * pitchMod, now);

      const nGain = audioCtx.createGain();
      nGain.gain.setValueAtTime(0.45, now);
      nGain.gain.exponentialRampToValueAtTime(0.001, now + dur);

      noise.connect(filter);
      filter.connect(nGain);
      nGain.connect(audioCtx.destination);
      noise.start(now);

      // Snap tone
      const osc = audioCtx.createOscillator();
      const oGain = audioCtx.createGain();
      osc.type = "sine";
      osc.frequency.setValueAtTime(520 * pitchMod, now);
      osc.frequency.exponentialRampToValueAtTime(130, now + 0.045);

      oGain.gain.setValueAtTime(0.45, now);
      oGain.gain.exponentialRampToValueAtTime(0.001, now + 0.045);

      osc.connect(oGain);
      oGain.connect(audioCtx.destination);
      osc.start(now);
      osc.stop(now + 0.05);

    } else {
      // Standard Key: Crisp, punchy mechanical switch click + tactile bottom-out
      const dur = 0.035;
      const bufSize = Math.floor(audioCtx.sampleRate * dur);
      const buffer = audioCtx.createBuffer(1, bufSize, audioCtx.sampleRate);
      const data = buffer.getChannelData(0);
      for (let i = 0; i < bufSize; i++) {
        data[i] = (Math.random() * 2 - 1) * Math.exp(-i / (bufSize * 0.18));
      }
      const noise = audioCtx.createBufferSource();
      noise.buffer = buffer;

      const filter = audioCtx.createBiquadFilter();
      filter.type = "bandpass";
      filter.frequency.setValueAtTime(2600 * pitchMod, now);
      filter.Q.setValueAtTime(2.2, now);

      const nGain = audioCtx.createGain();
      nGain.gain.setValueAtTime(0.5, now);
      nGain.gain.exponentialRampToValueAtTime(0.001, now + dur);

      noise.connect(filter);
      filter.connect(nGain);
      nGain.connect(audioCtx.destination);
      noise.start(now);

      // Resonant Body Thud (tactile bottom-out clack)
      const osc = audioCtx.createOscillator();
      const oGain = audioCtx.createGain();
      osc.type = "sine";
      osc.frequency.setValueAtTime(380 * pitchMod, now);
      osc.frequency.exponentialRampToValueAtTime(85, now + 0.04);

      oGain.gain.setValueAtTime(0.45, now);
      oGain.gain.exponentialRampToValueAtTime(0.001, now + 0.04);

      osc.connect(oGain);
      oGain.connect(audioCtx.destination);
      osc.start(now);
      osc.stop(now + 0.045);
    }
  } catch (e) {
    console.error("Audio playback error:", e);
  }
}
window.playKeySound = playKeySound;

/* ── Grapheme Utilities ── */
const segmenter = (typeof Intl !== "undefined" && Intl.Segmenter)
  ? new Intl.Segmenter("hi", {granularity: "grapheme"}) : null;
function graphemes(str) {
  if (segmenter) return Array.from(segmenter.segment(str), s => s.segment);
  return Array.from(str);
}

