const el = id => document.getElementById(id);
const passageEl = el("passage"), inputEl = el("input"), tip = el("tip");
const timeV = el("timeV"), wpmV = el("wpmV"), accV = el("accV"), errV = el("errV");
const overlay = el("overlay"), sel = el("passageSel"), engWarn = el("engWarn");

/* ── Passage Loading ── */
function fillSelect() {
  sel.innerHTML = "";
  const list = (LANGS[lang] && LANGS[lang][level]) ? LANGS[lang][level] : (LANGS[lang]["medium"] || []);
  list.forEach((p, i) => {
    const o = document.createElement("option");
    o.value = i; o.textContent = p.name;
    sel.appendChild(o);
  });
  const lbl = el("passageLabel");
  if (lbl) {
    lbl.textContent = (level === "words") ? "Words Set" : "Passage";
  }
}

function updateHeaderBanners(p) {
  const testHeader = el("testHeaderTitle");
  if (testHeader) {
    testHeader.textContent = p ? `Typing Test Id 39041 - ${p.name}` : "Typing Test";
  }
  const testSub = el("testSubTitle");
  if (testSub) {
    testSub.textContent = (lang === "hindi")
      ? "UP Police SI/ASI/Computer Operator Hindi Typing (Mangal Inscript)"
      : "UP Police SI/ASI/Computer Operator English Typing";
  }
}

function loadPassage() {
  const list = (LANGS[lang] && LANGS[lang][level]) ? LANGS[lang][level] : (LANGS[lang]["medium"] || []);
  const p = list[+sel.value || 0] || list[0];
  if (!p) return;
  updateHeaderBanners(p);
  const words = p.text.split(" ");
  passageEl.innerHTML = "";
  wordsData = [];
  words.forEach((wtext, wi) => {
    const wspan = document.createElement("span");
    wspan.className = "word";
    wspan.dataset.word = wtext;
    const gs = graphemes(wtext);
    const wspans = gs.map(g => {
      const s = document.createElement("span");
      s.className = "g";
      s.textContent = g;
      wspan.appendChild(s);
      return s;
    });
    passageEl.appendChild(wspan);
    let spaceSpan = null;
    if (wi < words.length - 1) {
      spaceSpan = document.createElement("span");
      spaceSpan.className = "g";
      spaceSpan.textContent = " ";
      passageEl.appendChild(spaceSpan);
    }
    wordsData.push({text: wtext, g: gs, el: wspan, spans: wspans, spaceSpan});
  });
  if (wordsData[0] && hlMode !== "off") {
    wordsData[0].el.classList.add("active");
    wordsData[0].spans[0].classList.add("cur");
  }
  attachTooltips();
}

/* ── Tooltips ── */
function attachTooltips() {
  if (!passageEl) return;
  passageEl.querySelectorAll(".word").forEach(w => {
    w.addEventListener("mouseenter", () => showTip(w));
    w.addEventListener("mouseleave", hideTip);
    w.addEventListener("touchstart", () => { showTip(w); setTimeout(hideTip, 2500); }, {passive: true});
  });
}
function showTip(w) {
  const word = w.dataset.word;
  if (!word || !/[\u0900-\u097F]/.test(word)) return;
  const units = keysForWord(word);
  if (!units || units.length === 0) return;
  tip.innerHTML = '<div class="t-word">' + word + ' <small>— Inscript keys</small></div>' +
    '<div class="chips">' + units.map(u =>
      '<div class="chip"><div class="u">' + u.u + '</div><div class="kk">' + u.k + '</div></div>'
    ).join("") + '</div>';
  tip.style.display = "block";
  const r = w.getBoundingClientRect(), tr = tip.getBoundingClientRect();
  let x = r.left + r.width / 2 - tr.width / 2;
  x = Math.max(8, Math.min(x, window.innerWidth - tr.width - 8));
  let y = r.top - tr.height - 10;
  if (y < 8) y = r.bottom + 10;
  tip.style.left = x + "px";
  tip.style.top = y + "px";
}
function hideTip() { if (tip) tip.style.display = "none"; }

/* ── Timer ── */
function fmt(t) { return Math.floor(t / 60) + ":" + String(t % 60).padStart(2, "0"); }
function startTimer() {
  started = true;
  startTime = Date.now();
  timerId = setInterval(() => {
    timeLeft--;
    const formatted = fmt(timeLeft);
    timeV.textContent = formatted;
    if (el("examTimeV")) el("examTimeV").textContent = formatted;
    if (timeLeft <= 10) el("timerStat").classList.add("low");
    updateStats();
    if (timeLeft <= 0) finish();
  }, 1000);
}
function elapsedMin() {
  if (!started || !startTime) return 1 / 60;
  const m = (Date.now() - startTime) / 60000;
  return Math.min(Math.max(m, 1 / 60), durationSec / 60);
}

/* ── Word Comparison & Error Classification (UP Police Official LCS/Diff Alignment) ── */
const PUNCT_REGEX = /[\.,!?:;\"'()\-—–/\\“”‘’।]/g;
function stripPunct(s) {
  return (s || "").replace(PUNCT_REGEX, "");
}

function levenshtein(a, b) {
  if (a === b) return 0;
  const la = a.length, lb = b.length;
  if (la === 0) return lb;
  if (lb === 0) return la;
  let prev = new Array(lb + 1);
  for (let j = 0; j <= lb; j++) prev[j] = j;
  for (let i = 1; i <= la; i++) {
    const curr = new Array(lb + 1);
    curr[0] = i;
    const ca = a.charCodeAt(i - 1);
    for (let j = 1; j <= lb; j++) {
      const cost = (ca === b.charCodeAt(j - 1)) ? 0 : 1;
      curr[j] = Math.min(prev[j] + 1, curr[j - 1] + 1, prev[j - 1] + cost);
    }
    prev = curr;
  }
  return prev[lb];
}

function wordSimilarity(a, b) {
  if (!a || !b) return 0;
  if (a === b) return 1;
  const maxLen = Math.max(a.length, b.length);
  if (maxLen === 0) return 1;
  const dist = levenshtein(a, b);
  return Math.max(0, 1 - (dist / maxLen));
}

function matchScore(target, typed) {
  if (target === typed) return 12;
  const strippedT = stripPunct(target);
  const strippedU = stripPunct(typed);
  if (strippedT === strippedU && strippedT.length > 0) return 9;
  if (lang === "english") {
    if (target.toLowerCase() === typed.toLowerCase()) return 8;
    if (strippedT.toLowerCase() === strippedU.toLowerCase() && strippedT.length > 0) return 7;
  }
  const sim = wordSimilarity(target, typed);
  if (sim >= 0.5) {
    return 3 + 6 * sim;
  }
  return -2;
}

function getTypedTokens(val, isFinished) {
  if (!val) return [];
  const hasTrailingSpace = /\s$/.test(val);
  const words = val.trim().split(/\s+/).filter(w => w.length > 0);
  if (words.length === 0) return [];
  
  return words.map((text, idx) => ({
    text,
    isCurrent: !isFinished && !hasTrailingSpace && (idx === words.length - 1)
  }));
}

function alignWordsPrefix(targets, typeds) {
  const N = targets.length;
  const M = typeds.length;
  if (M === 0) return { aligned: [], unattempted: [], bestI: 0 };

  const GAP_TARGET = -4; // Omission penalty
  const GAP_TYPED = -4;  // Addition penalty
  const MAX_FORWARD_LOOKAHEAD = 12; // Maximum words to skip ahead in target
  const maxN = Math.min(N, M + MAX_FORWARD_LOOKAHEAD + 5);

  const dp = [];
  const choice = []; // 0: diag (pair), 1: up (omission), 2: left (addition)

  for (let i = 0; i <= maxN; i++) {
    dp[i] = new Float32Array(M + 1).fill(-Infinity);
    choice[i] = new Uint8Array(M + 1);
  }

  dp[0][0] = 0;
  for (let i = 1; i <= Math.min(maxN, MAX_FORWARD_LOOKAHEAD); i++) {
    dp[i][0] = dp[i - 1][0] + GAP_TARGET;
    choice[i][0] = 1;
  }
  for (let j = 1; j <= M; j++) {
    dp[0][j] = dp[0][j - 1] + GAP_TYPED;
    choice[0][j] = 2;
  }

  for (let j = 1; j <= M; j++) {
    const uWord = typeds[j - 1].text;
    const minI = Math.max(1, j - 5);
    const maxI = Math.min(maxN, j + MAX_FORWARD_LOOKAHEAD);

    for (let i = minI; i <= maxI; i++) {
      const tWord = targets[i - 1];
      const scoreDiag = dp[i - 1][j - 1] + matchScore(tWord, uWord);
      const scoreUp = dp[i - 1][j] + GAP_TARGET;
      const scoreLeft = dp[i][j - 1] + GAP_TYPED;

      let bestScore = scoreDiag;
      let bestChoice = 0;

      if (scoreUp > bestScore) {
        bestScore = scoreUp;
        bestChoice = 1;
      }
      if (scoreLeft > bestScore) {
        bestScore = scoreLeft;
        bestChoice = 2;
      }

      dp[i][j] = bestScore;
      choice[i][j] = bestChoice;
    }
  }

  // Find best ending target index i at j = M
  let bestI = M;
  let bestScore = -Infinity;
  const startCheck = Math.max(1, M - 5);
  const endCheck = Math.min(maxN, M + MAX_FORWARD_LOOKAHEAD);
  for (let i = startCheck; i <= endCheck; i++) {
    if (dp[i][M] > bestScore) {
      bestScore = dp[i][M];
      bestI = i;
    }
  }

  // Backtrack from (bestI, M)
  const aligned = [];
  let i = bestI, j = M;
  while (i > 0 || j > 0) {
    const c = (i >= 0 && j >= 0) ? choice[i][j] : (i > 0 ? 1 : 2);
    if (i > 0 && j > 0 && c === 0) {
      aligned.push({
        targetIdx: i - 1,
        target: targets[i - 1],
        typedIdx: j - 1,
        typed: typeds[j - 1].text,
        isCurrent: typeds[j - 1].isCurrent,
        type: "pair"
      });
      i--; j--;
    } else if (i > 0 && (j === 0 || c === 1)) {
      aligned.push({
        targetIdx: i - 1,
        target: targets[i - 1],
        typedIdx: null,
        typed: null,
        isCurrent: false,
        type: "omission"
      });
      i--;
    } else {
      aligned.push({
        targetIdx: null,
        target: null,
        typedIdx: j - 1,
        typed: typeds[j - 1].text,
        isCurrent: typeds[j - 1].isCurrent,
        type: "addition"
      });
      j--;
    }
  }
  aligned.reverse();

  // All remaining words from bestI to N-1 are unattempted
  const unattempted = [];
  for (let k = bestI; k < N; k++) {
    unattempted.push({
      targetIdx: k,
      target: targets[k],
      typedIdx: null,
      typed: "—",
      status: "skip",
      type: "unattempted"
    });
  }

  return { aligned, unattempted, bestI };
}

let lastTestStats = null;
let currentReviewFilter = "mistakes";

function compare() {
  wordsData.forEach(w => {
    w.el.classList.remove("active");
    w.spans.forEach(s => s.classList.remove("ok", "bad", "half-bad", "cur"));
    if (w.spaceSpan) w.spaceSpan.classList.remove("ok", "bad", "half-bad", "cur");
  });

  const typeds = getTypedTokens(inputEl.value, finished);
  const targetWords = wordsData.map(w => w.text);

  if (typeds.length === 0) {
    if (wordsData[0] && hlMode !== "off") {
      wordsData[0].el.classList.add("active");
      wordsData[0].spans[0].classList.add("cur");
    }
    return {
      okWords: 0,
      fullMistakes: 0,
      halfMistakes: 0,
      omissionsCount: 0,
      totalMistakes: 0,
      pureWords: 0,
      attempted: 0,
      reviewItems: [],
      unattemptedItems: wordsData.map((w, idx) => ({
        index: idx + 1,
        targetWord: w.text,
        typedWord: "—",
        status: "skip",
        category: "Unattempted / छूटा हुआ शब्द",
        reason: "समय समाप्त होने के कारण यह शब्द टाइप नहीं हो पाया (Not attempted within time).",
        penalty: 0
      })),
      reachedEnd: false
    };
  }

  const { aligned, unattempted, bestI } = alignWordsPrefix(targetWords, typeds);

  // Pre-detect transpositions in pairs
  const transposedIndices = new Set();
  for (let k = 0; k < aligned.length - 1; k++) {
    const a1 = aligned[k], a2 = aligned[k + 1];
    if (a1.type === "pair" && a2.type === "pair" && !a1.isCurrent && !a2.isCurrent) {
      if (a1.typed === a2.target && a2.typed === a1.target && a1.target !== a2.target) {
        transposedIndices.add(k);
        transposedIndices.add(k + 1);
      }
    }
  }

  let okWords = 0;
  let fullMistakes = 0;
  let halfMistakes = 0;
  let omissionsCount = 0;
  let attempted = 0;
  let currentActiveTargetIdx = null;

  const reviewItems = [];

  aligned.forEach((item, k) => {
    if (item.type === "pair") {
      const W = wordsData[item.targetIdx];
      const targetWord = item.target;
      const typedWord = item.typed;
      const isCurrent = item.isCurrent;

      let mistakeType = null; // null (clean match), "half", "full"
      let category = "Correct / शुद्ध";
      let reason = "सही शब्द (Word matches target)";

      if (typedWord === targetWord) {
        mistakeType = null;
        category = "Correct / शुद्ध";
        reason = "सही शब्द (Word matches target)";
      } else if (transposedIndices.has(k)) {
        mistakeType = "half";
        category = "Transposition / शब्दों का उलट-पलट";
        reason = "शब्दों का क्रम बदल गया (Transposed with adjacent word)";
      } else {
        const strippedTyped = stripPunct(typedWord);
        const strippedTarget = stripPunct(targetWord);

        if (strippedTyped === strippedTarget && strippedTyped.length > 0) {
          mistakeType = "half";
          category = "Punctuation / विराम चिह्न";
          reason = `विराम चिह्न छूटा या गलत लगा (Punctuation mismatch: expected "${targetWord}")`;
        } else if (lang === "english") {
          if (typedWord.toLowerCase() === targetWord.toLowerCase()) {
            mistakeType = "half";
            category = "Capitalisation / छोटा-बड़ा अक्षर";
            reason = `कैपिटल/स्मॉल अक्षर की अशुद्धि (Case mismatch: expected "${targetWord}")`;
          } else if (strippedTyped.toLowerCase() === strippedTarget.toLowerCase() && strippedTyped.length > 0) {
            mistakeType = "half";
            category = "Punctuation & Case";
            reason = `विराम चिह्न व केस दोनों में अशुद्धि (Case & punctuation mismatch: expected "${targetWord}")`;
          } else {
            mistakeType = "full";
            category = "Spelling / गलत शब्द";
            reason = `हिज्जे या शब्द गलत है (Spelling error / wrong word: expected "${targetWord}")`;
          }
        } else {
          mistakeType = "full";
          category = "Spelling / गलत शब्द";
          reason = `मात्रा, वर्ण या शब्द गलत है (Spelling error: expected "${targetWord}")`;
        }
      }

      // Coloring in live passage
      if (hlMode !== "off") {
        if (isCurrent) {
          currentActiveTargetIdx = item.targetIdx;
          W.el.classList.add("active");
          const tw = graphemes(typedWord);
          for (let gi = 0; gi < W.g.length; gi++) {
            const s = W.spans[gi];
            if (gi < tw.length) {
              if (tw[gi] === W.g[gi]) s.classList.add("ok");
              else s.classList.add("bad");
            }
          }
          let curSpan = null;
          if (tw.length < W.g.length) curSpan = W.spans[tw.length];
          else if (W.spaceSpan) curSpan = W.spaceSpan;
          if (curSpan) {
            curSpan.classList.add("cur");
            curSpan.scrollIntoView({block: "nearest"});
          }
        } else {
          const cls = mistakeType === null ? "ok" : (mistakeType === "half" ? "half-bad" : "bad");
          W.spans.forEach(s => s.classList.add(cls));
          if (W.spaceSpan) W.spaceSpan.classList.add(cls);
        }
      }

      if (!isCurrent) {
        attempted++;
        if (mistakeType === null) {
          okWords++;
        } else if (mistakeType === "half") {
          halfMistakes++;
        } else {
          fullMistakes++;
        }

        reviewItems.push({
          index: item.targetIdx + 1,
          targetWord,
          typedWord,
          status: mistakeType === null ? "ok" : mistakeType,
          category,
          reason,
          penalty: mistakeType === null ? 0 : (mistakeType === "half" ? 0.5 : 1.0)
        });
      }

    } else if (item.type === "omission") {
      const W = wordsData[item.targetIdx];
      // Since item is in aligned (before bestI), this is an omission in the middle of typed text!
      attempted++;
      fullMistakes++;
      omissionsCount++;

      if (hlMode !== "off") {
        W.spans.forEach(s => s.classList.add("bad"));
        if (W.spaceSpan) W.spaceSpan.classList.add("bad");
      }

      reviewItems.push({
        index: item.targetIdx + 1,
        targetWord: item.target,
        typedWord: "— (छूटा हुआ)",
        status: "omission",
        category: "Omission / छूटा हुआ शब्द",
        reason: `गद्यांश का यह शब्द टाइप करने से छूट गया (Word omitted from passage: expected "${item.target}")`,
        penalty: 1.0
      });

    } else if (item.type === "addition") {
      // Extra word typed
      if (!item.isCurrent) {
        attempted++;
        fullMistakes++;

        reviewItems.push({
          index: (bestI > 0 ? bestI : 1),
          targetWord: "— (अतिरिक्त शब्द)",
          typedWord: item.typed,
          status: "full",
          category: "Addition / अतिरिक्त शब्द",
          reason: `गद्यांश में न होने वाला अतिरिक्त शब्द टाइप किया गया (Extra word typed: "${item.typed}")`,
          penalty: 1.0
        });
      }
    }
  });

  // Unattempted items (words from bestI to targetWords.length - 1)
  const unattemptedItems = unattempted.map(u => ({
    index: u.targetIdx + 1,
    targetWord: u.target,
    typedWord: "—",
    status: "skip",
    category: "Unattempted / छूटा हुआ शब्द",
    reason: "समय समाप्त होने के कारण यह शब्द टाइप नहीं हो पाया (Not attempted within time).",
    penalty: 0
  }));

  // If live typing and no token is currently in-progress, set cursor on next unattempted word
  if (!finished && currentActiveTargetIdx === null && hlMode !== "off") {
    const nextIdx = bestI;
    if (nextIdx < wordsData.length) {
      const nextW = wordsData[nextIdx];
      nextW.el.classList.add("active");
      if (nextW.spans[0]) {
        nextW.spans[0].classList.add("cur");
        nextW.spans[0].scrollIntoView({block: "nearest"});
      }
    }
  }

  const totalMistakes = fullMistakes + (halfMistakes * 0.5);
  const pureWords = Math.max(0, attempted - totalMistakes);
  const reachedEnd = (bestI >= wordsData.length);

  return {
    okWords,
    fullMistakes,
    halfMistakes,
    omissionsCount,
    totalMistakes,
    pureWords,
    attempted,
    reviewItems,
    unattemptedItems,
    reachedEnd
  };
}

/* ── Stats ── */
function updateStats() {
  const s = compare();
  const min = elapsedMin();
  const keystrokes = Array.from(inputEl.value).length;
  const totalPassageWords = wordsData.length;
  const grossSpeed = min > 0 ? (s.attempted / min) : 0;
  const netSpeed = min > 0 ? (s.pureWords / min) : 0;

  // 15-min Exam Mode uses total passage words (Official Exam Rule) upon finish
  // 1, 2, 5, 10 min Practice Modes use total attempted words
  const is15MinExam = (durationSec >= 15 * 60);
  const accBase = (is15MinExam && finished) ? totalPassageWords : s.attempted;
  const acc = (accBase > 0) ? ((s.pureWords * 100) / accBase) : 0;

  wpmV.textContent = started ? netSpeed.toFixed(1) : "0";
  accV.textContent = started ? (acc.toFixed(1) + "%") : "0%";
  errV.textContent = started ? `${s.fullMistakes} / ${s.halfMistakes}` : "0 / 0";

  return {...s, min, grossSpeed, netSpeed, speed: netSpeed, acc, totalPassageWords, keystrokes};
}

/* ── Finish & Reset ── */
function finish() {
  if (finished) return;
  finished = true;
  clearInterval(timerId);
  inputEl.disabled = true;
  const s = updateStats();
  lastTestStats = s;

  const name = el("nameIn").value.trim();
  el("rName").textContent = name || "—";
  el("rWpm").textContent = s.netSpeed.toFixed(2);
  if (el("rPassageTotal")) el("rPassageTotal").textContent = s.totalPassageWords;
  el("rTotal").textContent = s.attempted;
  if (el("rPure")) el("rPure").textContent = (Number.isInteger(s.pureWords) ? s.pureWords : s.pureWords.toFixed(1));
  if (el("rFullErr")) el("rFullErr").textContent = s.fullMistakes;
  if (el("rHalfErr")) el("rHalfErr").textContent = s.halfMistakes;
  if (el("rTotalErr")) el("rTotalErr").textContent = (Number.isInteger(s.totalMistakes) ? s.totalMistakes : s.totalMistakes.toFixed(1));
  el("rKeys").textContent = s.keystrokes;
  el("rBackspaces").textContent = backspaceCount;
  el("rAcc").textContent = s.acc.toFixed(2);
  el("rGross").textContent = s.grossSpeed.toFixed(2);
  el("rTime").textContent = s.min.toFixed(2);

  // UP Police Qualifying Evaluation
  const reqSpeed = (lang === "hindi") ? 25.0 : 30.0;
  const reqAcc = 85.0;
  const isQualified = (s.netSpeed >= reqSpeed && s.acc >= reqAcc);
  const qualBadge = el("rQualBadge");
  const rTrophy = el("rTrophy");

  if (qualBadge) {
    if (isQualified) {
      qualBadge.className = "r-qual-badge qual-pass";
      qualBadge.innerHTML = `✓ QUALIFIED (उत्तीर्ण) — ${s.netSpeed.toFixed(2)} WPM / ${s.acc.toFixed(1)}% Acc`;
      if (rTrophy) rTrophy.textContent = "🏆";
    } else {
      qualBadge.className = "r-qual-badge qual-fail";
      let failReasons = [];
      if (s.netSpeed < reqSpeed) failReasons.push(`Speed < ${reqSpeed} WPM (कट-ऑफ ${reqSpeed})`);
      if (s.acc < reqAcc) failReasons.push(`Accuracy < ${reqAcc}% (कट-ऑफ 85%)`);
      qualBadge.innerHTML = `✗ NOT QUALIFIED (अनुत्तीर्ण) — ${failReasons.join(", ")}`;
      if (rTrophy) rTrophy.textContent = "⚠️";
    }
  }

  overlay.classList.add("show");
}

function reset() {
  clearInterval(timerId); timerId = null;
  started = false; finished = false;
  startTime = 0;
  backspaceCount = 0;
  lastTestStats = null;
  timeLeft = durationSec;
  inputEl.value = ""; inputEl.disabled = false;
  const formatted = fmt(timeLeft);
  timeV.textContent = formatted;
  if (el("examTimeV")) el("examTimeV").textContent = formatted;
  el("timerStat").classList.remove("low");
  wpmV.textContent = "0"; accV.textContent = "0%"; errV.textContent = "0 / 0";
  overlay.classList.remove("show");
  if (el("reviewOverlay")) el("reviewOverlay").classList.remove("show");
  engWarn.classList.remove("show");
  hideTip();
  if (hlMode === "off") {
    passageEl.classList.add("no-highlight");
  } else {
    passageEl.classList.remove("no-highlight");
  }
  loadPassage();
  updateHintsAndPlaceholder();
  const testView = el("viewTest");
  if (testView && testView.style.display !== "none") {
    inputEl.focus();
  }
}

/* ── Review Mode Functions ── */
function escapeHtml(str) {
  if (!str) return "";
  return String(str).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
}

function showWordDetail(item) {
  const detailCard = el("revDetailCard");
  const badge = el("rdBadge");
  badge.className = `rd-badge badge-${item.status}`;
  badge.textContent = item.status === "ok" ? "Correct (शुद्ध)"
    : item.status === "half" ? "Half Mistake (0.5)"
    : item.status === "omission" ? "Omission (छूटा हुआ - 1.0)"
    : item.status === "full" ? "Full Mistake (1.0)"
    : "Unattempted (छूटा हुआ)";

  el("rdIndex").textContent = `Word #${item.index}`;
  el("rdTarget").textContent = item.targetWord;
  el("rdTyped").textContent = item.typedWord;
  el("rdReason").textContent = item.reason;
  detailCard.style.display = "block";
}

function renderReviewPassage(stats) {
  const revPassageEl = el("revPassage");
  revPassageEl.innerHTML = "";
  el("revDetailCard").style.display = "none";

  const allItems = [...stats.reviewItems, ...stats.unattemptedItems];
  
  allItems.forEach((item, i) => {
    const span = document.createElement("span");
    span.className = `rev-word w-${item.status}`;
    span.textContent = (item.status === "full" && item.targetWord && item.targetWord.startsWith("—")) ? item.typedWord : item.targetWord;
    span.dataset.idx = i;
    
    span.addEventListener("click", () => {
      revPassageEl.querySelectorAll(".rev-word").forEach(w => w.classList.remove("w-selected"));
      span.classList.add("w-selected");
      showWordDetail(item);
    });

    revPassageEl.appendChild(span);
    revPassageEl.appendChild(document.createTextNode(" "));
  });

  const firstMistake = allItems.find(it => it.status === "full" || it.status === "half" || it.status === "omission") || allItems[0];
  if (firstMistake) {
    const idx = allItems.indexOf(firstMistake);
    const span = revPassageEl.querySelector(`[data-idx="${idx}"]`);
    if (span) {
      span.classList.add("w-selected");
      showWordDetail(firstMistake);
    }
  }
}

function renderReviewTable(stats, filter) {
  currentReviewFilter = filter;
  const tbody = el("revTableBody");
  tbody.innerHTML = "";
  const empty = el("revEmpty");

  const allItems = [...stats.reviewItems, ...stats.unattemptedItems];
  let filtered = [];

  if (filter === "mistakes") {
    filtered = stats.reviewItems.filter(it => it.status === "full" || it.status === "half" || it.status === "omission");
  } else if (filter === "full") {
    filtered = stats.reviewItems.filter(it => it.status === "full");
  } else if (filter === "half") {
    filtered = stats.reviewItems.filter(it => it.status === "half");
  } else if (filter === "omission") {
    filtered = stats.reviewItems.filter(it => it.status === "omission");
  } else {
    filtered = allItems;
  }

  const mistakesCount = stats.fullMistakes + stats.halfMistakes;
  el("cntMistakes").textContent = mistakesCount;
  el("cntFull").textContent = stats.fullMistakes - (stats.omissionsCount || 0);
  el("cntHalf").textContent = stats.halfMistakes;
  if (el("cntOmission")) el("cntOmission").textContent = (stats.omissionsCount || 0);
  el("cntAll").textContent = allItems.length;

  if (filtered.length === 0) {
    empty.style.display = "block";
    return;
  }
  empty.style.display = "none";

  filtered.forEach(item => {
    const tr = document.createElement("tr");
    const badgeClass = item.status;
    const badgeText = item.status === "ok" ? "Correct"
      : item.status === "half" ? "Half (0.5)"
      : item.status === "omission" ? "Omission (1.0)"
      : item.status === "full" ? "Full (1.0)"
      : "Skip";

    tr.innerHTML = `
      <td>${item.index}</td>
      <td class="dev-text" style="color:var(--ok)"><b>${escapeHtml(item.targetWord)}</b></td>
      <td class="dev-text" style="color:${item.status === 'ok' ? 'var(--ok)' : (item.status === 'half' ? '#fbbf24' : 'var(--bad)')}">
        <b>${escapeHtml(item.typedWord)}</b>
      </td>
      <td><span class="tb-badge ${badgeClass}">${badgeText}</span></td>
      <td>${escapeHtml(item.reason)}</td>
      <td style="font-family:var(--mono);font-weight:600;color:${item.penalty > 0 ? 'var(--bad)' : 'var(--text-3)'}">
        ${item.penalty > 0 ? `-${item.penalty}` : '0.0'}
      </td>
    `;

    tr.addEventListener("click", () => {
      const revPassageEl = el("revPassage");
      const allItems = [...stats.reviewItems, ...stats.unattemptedItems];
      const idx = allItems.indexOf(item);
      if (idx !== -1) {
        const span = revPassageEl.querySelector(`[data-idx="${idx}"]`);
        if (span) {
          revPassageEl.querySelectorAll(".rev-word").forEach(w => w.classList.remove("w-selected"));
          span.classList.add("w-selected");
          span.scrollIntoView({behavior: "smooth", block: "center"});
          showWordDetail(item);
        }
      }
    });

    tbody.appendChild(tr);
  });
}

function openReviewModal() {
  if (!lastTestStats) return;
  overlay.classList.remove("show");
  
  el("revPure").textContent = Number.isInteger(lastTestStats.pureWords) ? lastTestStats.pureWords : lastTestStats.pureWords.toFixed(1);
  el("revFull").textContent = lastTestStats.fullMistakes;
  el("revHalf").textContent = lastTestStats.halfMistakes;
  el("revTotalErr").textContent = Number.isInteger(lastTestStats.totalMistakes) ? lastTestStats.totalMistakes : lastTestStats.totalMistakes.toFixed(1);
  el("revAcc").textContent = lastTestStats.acc.toFixed(2) + "%";
  el("revSpeed").textContent = lastTestStats.netSpeed.toFixed(2) + " WPM";

  renderReviewPassage(lastTestStats);
  renderReviewTable(lastTestStats, "mistakes");

  document.querySelectorAll("#revFilterSeg button").forEach(b => {
    b.classList.toggle("active", b.dataset.filter === "mistakes");
  });

  el("reviewOverlay").classList.add("show");
}

function closeReviewModal() {
  el("reviewOverlay").classList.remove("show");
  overlay.classList.add("show");
}

/* ── Inscript Typing & Key Sounds ── */
inputEl.addEventListener("keydown", e => {
  if (e.key === "Backspace") backspaceCount++;
  const soundType = e.key === " " ? "space" : (e.key === "Backspace" ? "backspace" : "key");
  playKeySound(soundType);
  if (lang !== "hindi") return;
  if (kbMode !== "inscript") return;
  if (e.ctrlKey || e.metaKey || e.altKey) return;
  const k = e.key;
  if (k.length !== 1) return;
  if (k === " " || k === "," || k === ".") return;
  const mapped = INS[k];
  e.preventDefault();
  if (mapped === undefined && !/[()\-!?]/.test(k)) return;
  const insert = mapped !== undefined ? mapped : k;
  const st = inputEl.selectionStart, en = inputEl.selectionEnd;
  inputEl.value = inputEl.value.slice(0, st) + insert + inputEl.value.slice(en);
  const pos = st + insert.length;
  inputEl.setSelectionRange(pos, pos);
  inputEl.dispatchEvent(new Event("input", {bubbles: true}));
});

/* ── Events ── */
inputEl.addEventListener("input", () => {
  if (finished) return;
  if (!started && inputEl.value.length > 0) startTimer();
  if (lang === "hindi" && /[A-Za-z]/.test(inputEl.value)) engWarn.classList.add("show");
  else if (lang === "english" && /[\u0900-\u097F]/.test(inputEl.value)) engWarn.classList.add("show");
  else engWarn.classList.remove("show");
  const s = updateStats();
  const tws = getTypedTokens(inputEl.value, false);
  const lastW = wordsData[wordsData.length - 1];
  if (tws.length > wordsData.length ||
     (tws.length === wordsData.length && !tws[tws.length - 1].isCurrent && graphemes(tws[tws.length - 1].text).length >= lastW.g.length)) {
    finish();
  }
});
inputEl.addEventListener("paste", e => e.preventDefault());

